// The play frontend (elunic seat bridge) walks the player straight onto a chair and turns it; the scripting API can
// neither walk inside a tile nor set the facing direction. Only this script's iframe is trusted by the bridge.
const face = (direction) => window.parent.postMessage({ type: "elunic-face", direction }, "*");
const sit = (c) => window.parent.postMessage({ type: "elunic-sit", x: c[0], y: c[1], direction: c[2] }, "*");
// Images without the seat bridge do not answer the hello: the chair snap then keeps teleporting.
let seatBridge = false;
window.addEventListener("message", (e) => { if (e.data && e.data.type === "elunic-seat-bridge") seatBridge = true; });
window.parent.postMessage({ type: "elunic-seat-hello" }, "*");
// facing of the chair at (x, y), if there is one (calendar seats are tile centres, wide chairs are centred on two tiles)
const facingAt = (x, y) => (CHAIRS.find((c) => Math.hypot(c[0] - x, c[1] - y) <= 20) || [])[2];

WA.onInit().then(async () => {
    const dbg = [];
    try {
        // An explicit position in the link (e.g. #start-area) wins.
        const hash = WA.room.hashParameters || {};
        const uuid = WA.player.uuid;
        dbg.push("uuid=" + uuid, "hashKeys=" + Object.keys(hash).join(","));
        // Only a real position in the link (non-empty hash value, e.g. #start-area) wins over the desk.
        if (Object.values(hash).some((v) => v !== undefined && v !== null && v !== "")) return;
        if (!uuid) return;
        const wamUrl = new URL("elunic-office.wam", WA.room.mapURL).toString();
        dbg.push("wam=" + wamUrl);
        const res = await fetch(wamUrl, { cache: "no-store" });
        dbg.push("status=" + res.status);
        const wam = await res.json();
        const own = (wam.areas || []).find((area) =>
            (area.properties || []).some((p) => p.type === "personalAreaPropertyData" && p.ownerId === uuid)
        );
        dbg.push("own=" + (own ? own.name : "none"));
        if (!own) return;
        const spawn = SPAWNS[own.id] || [own.x + own.width / 2, own.y + own.height / 2];
        await WA.player.teleport(spawn[0], spawn[1]);
        if (spawn[2]) face(spawn[2]);
        dbg.push("teleported");
    } catch (e) {
        console.warn("elunic desk spawn failed", e);
        dbg.push("error=" + e);
    } finally {
        console.info("[elunic] desk spawn: " + dbg.join(" | "));
    }
});

// --- calendar meetings: during an accepted meeting, walk to the seat the wa-calendar service assigned, set
// "Do not disturb", and walk back + restore the previous status when the meeting ends. Meetings need a logged-in
// user (token); every player, anonymous ones included, pings so the service can list who is on the map.
WA.onInit().then(() => {
    let token;
    try { token = WA.player.userRoomToken; } catch (e) { token = undefined; }
    const api = new URL("/calendar-api/presence", WA.room.mapURL).toString();
    const status = (action) => window.parent.postMessage({ type: "elunic-status", action }, "*");
    const go = async (x, y) => {
        try {
            const r = await WA.player.moveTo(x, y, 10);
            if (r && r.cancelled) await WA.player.teleport(x, y);
        } catch (e) {
            await WA.player.teleport(x, y).catch(() => {});
        }
    };
    let active = null;   // { key, x, y, endsAt, back: {x, y} }
    const finished = new Set();   // meeting keys this page already left: a late response never restarts them
    let busy = false;
    async function leave() {
        finished.add(active.key);
        const back = active.back;
        active = null;
        await go(back.x, back.y);
        status("restore");
    }
    async function tick() {
        if (busy) return;
        busy = true;
        try {
            // The meeting end is known locally: leave on time even if the service is slow or down.
            if (active && Date.now() >= active.endsAt) await leave();
            const who = WA.player.uuid + "|" + WA.player.name;
            const body = { token: token || undefined, name: WA.player.name, id: WA.player.uuid };
            const res = await fetch(api, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
                signal: AbortSignal.timeout(10000) }).catch(() => null);
            if (!res || !res.ok) return;   // service unreachable: never start or move a meeting
            let meeting = (await res.json()).meeting;
            // The answer may be late: drop it if the meeting has ended meanwhile, was already left here, or the
            // player identity changed while it was on its way.
            if (who !== WA.player.uuid + "|" + WA.player.name) return;
            if (meeting && (meeting.endsAt <= Date.now() || finished.has(meeting.key))) meeting = null;
            if (meeting && (!active || active.key !== meeting.key || active.x !== meeting.x || active.y !== meeting.y)) {
                const back = active ? active.back : await WA.player.getPosition();
                active = { key: meeting.key, x: meeting.x, y: meeting.y, endsAt: meeting.endsAt, back };
                // "dnd" before the walk lets the bridge save the status from before the meeting; WorkAdventure resets
                // the status to online on every move, so "dnd" again after arriving (and after every later move).
                status("dnd");
                await go(meeting.x, meeting.y);
                const dir = facingAt(meeting.x, meeting.y);
                if (active && dir) face(dir);
                if (active) status("dnd");
            } else if (!meeting && active) {
                await leave();
            }
        } catch (e) {
            console.warn("elunic calendar", e);
        } finally {
            busy = false;
        }
    }
    // Moving resets the status to online. During a meeting, put "Do not disturb" back once the player stops.
    let settle;
    WA.player.onPlayerMove((ev) => {
        clearTimeout(settle);
        if (active && !ev.moving) settle = setTimeout(() => { if (active) status("dnd"); }, 500);
    });
    setTimeout(tick, 4000);          // after the desk spawn has placed the player
    setInterval(tick, 30000);
});

// --- chairs: stop close to a free chair and the player walks onto it (exactly centred) and turns to the table ---
WA.onInit().then(async () => {
    const SNAP_PX = 30;            // about one tile: walking past a chair does not pull the player onto it
    const TAKEN_PX = 16;           // another player this close to the chair centre sits on it
    try { await WA.players.configureTracking({ players: true, movement: true }); } catch (e) { console.warn(e); }
    const taken = (c) => {
        try {
            for (const p of WA.players.list()) {
                const pos = p.position;
                if (pos && Math.hypot(pos.x - c[0], pos.y - c[1]) <= TAKEN_PX) return true;
            }
        } catch (e) { /* no tracking: treat as free */ }
        return false;
    };
    WA.player.onPlayerMove((ev) => {
        if (ev.moving) return;
        let best = null, bestDist = Infinity;
        for (const c of CHAIRS) {
            const d = Math.hypot(c[0] - ev.x, c[1] - ev.y);
            if (d < bestDist) { best = c; bestDist = d; }
        }
        // The walk ends with a "stopped" event right on the chair (distance 0), which ends the loop.
        if (!best || bestDist < 1 || bestDist > SNAP_PX || taken(best)) return;
        if (seatBridge) sit(best);
        else WA.player.teleport(best[0], best[1]).catch(() => {});
    });
});

// --- gong: walk up to it, press space, enter a message; everybody in the room hears it and sees a banner ---
const GONG_EVENT = "elunic-gong";
// WA.room.mapURL is only available after WA.onInit(), so resolve URLs lazily.
const gongSound = () => new URL("elunic-gong.ogg", WA.room.mapURL).toString();
// Banner in the receiver's browser language: German for "de*", English otherwise.
function gongText(from, message) {
    return (navigator.language || "").toLowerCase().startsWith("de")
        ? from + " hat den Gong geschlagen: " + message
        : from + " hit the gong: " + message;
}
function ringGong(from, message) {
    try { WA.sound.loadSound(gongSound()).play({ volume: 0.7, loop: false }); } catch (e) { console.warn(e); }
    WA.ui.banner.openBanner({
        id: "elunic-gong", text: gongText(from, message),
        bgColor: "#7a5a12", textColor: "#ffffff", closable: true, timeToClose: 30000,
    });
}
WA.onInit().then(() => {
    WA.room.area.create({ name: "elunic-gong", x: 40 * 32, y: 19 * 32, width: 5 * 32, height: 2 * 32 });
    let action;
    WA.room.area.onEnter("elunic-gong").subscribe(() => {
        action = WA.ui.displayActionMessage({
            // Browser language: German for "de*", English otherwise.
            message: (navigator.language || "").toLowerCase().startsWith("de") ? "Leertaste: Gong schlagen" : "Space: hit the gong",
            callback: () => WA.ui.modal.openModal({
                src: new URL("gong.html", WA.room.mapURL).toString(),
                title: "Gong", position: "center", allowApi: true, allow: "autoplay",
            }),
        });
    });
    WA.room.area.onLeave("elunic-gong").subscribe(() => { if (action) action.remove(); action = undefined; });
    // Senders ring locally in gong.html; skip our own echo if the server reflects it.
    WA.event.on(GONG_EVENT).subscribe((ev) => {
        if (ev.senderId !== undefined && ev.senderId === WA.player.playerId) return;
        const d = ev.data || {};
        ringGong(String(d.from || "?"), String(d.message || "").slice(0, 200));
    });
});
